 Check(!new AiSettings().enabled&&!new AiSettings().allowPrivate,"AI and private sending disabled by default");Reject(()=>AiService.Validate(new AiSettings{enabled=true}),"enabled AI requires endpoint and model");Reject(()=>AiService.Validate(new AiSettings{endpoint="http://example.com/chat/completions"}),"external AI requires HTTPS");Reject(()=>AiService.Validate(new AiSettings{endpoint="https://example.com/chat?key=fixture"}),"AI endpoint query secrets rejected");
 var categories=new List<Category>{new Category{id="tech",name="技术"}};string normal=Response("{\"title\":\"离线阅读工具更新\",\"categoryId\":\"tech\",\"rating\":4,\"reason\":\"提供离线阅读与搜索，信息较完整。\"}");var result=AiService.Parse(normal,categories);Check(result.title=="离线阅读工具更新"&&result.rating==4&&result.categoryId=="tech","structured AI title/category/rating parsed");Check(!Data.Json().Serialize(result).Contains("private-thought"),"reasoning content never stored");Reject(()=>AiService.Parse(Response("{\"title\":\"x\",\"categoryId\":\"tech\",\"rating\":9}"),categories),"out-of-range rating rejected");Reject(()=>AiService.Parse("{\"choices\":[{\"finish_reason\":\"length\",\"message\":{\"content\":\"{}\"}}]}",categories),"truncated model result rejected");var unknown=AiService.Parse(Response("{\"title\":\"未知分类文章\",\"categoryId\":\"invented-category\",\"rating\":3}"),categories);Check(unknown.categoryId=="","AI cannot invent category IDs");var fence=AiService.Parse(Response("```json\n{\"title\":\"短标题\",\"categoryId\":\"tech\",\"rating\":3}\n```"),categories);Check(fence.title=="短标题","fenced JSON compatibility");
 var article=new Article{id="a",source="s",title=new string('长',200)+"[图片]",summary="离线阅读工具 https://private.example.com/path?token=fixture-source-token"};var settings=new AiSettings{enabled=true,endpoint="https://example.com/v1/chat/completions",model="normal-model"};string body=Data.Json().Serialize(AiService.Body(article,settings,categories));Check(!body.Contains("fixture-source-token")&&!body.Contains("private.example.com"),"article URLs removed from outgoing AI text");Check(Feeds.ShortTitle(article.title).Length<=45&&!Feeds.ShortTitle(article.title).Contains("[图片]"),"long fallback title compact without image placeholders");settings.mode="reasoning";settings.tokenField="max_completion_tokens";settings.reasoningEffort="high";var reasoning=AiService.Body(article,settings,categories);Check(reasoning.ContainsKey("max_completion_tokens")&&!reasoning.ContainsKey("max_tokens")&&Convert.ToString(reasoning["reasoning_effort"])=="high","reasoning mode uses selected compatible token field");Check(!reasoning.ContainsKey("temperature"),"reasoning requests omit unsupported sampling parameters");
 using(var server=new Server(normal)){var store=new Store(folder);store.State.categories=categories;store.State.sources.Add(new Source{id="s",name="私有来源",url="https://private.example.com/feed",privateSource=true});store.State.articles.Add(article);store.State.ai=new AiSettings{enabled=true,model="fixture-model",endpoint=server.Url,dailyLimit=1};store.State.credentials["s"]=new RequestProfile{mode="bearer",token="fixture-source-token"};store.State.credentials[AiService.CredentialKey]=new RequestProfile{mode="bearer",token="fixture-ai-token"};var service=new AiService(store);Reject(()=>service.Analyze("a").GetAwaiter().GetResult(),"private content requires explicit opt-in");Check(server.Requests==0,"blocked private content makes no network request");Check(store.State.aiHistory.Last().status=="blocked"&&store.State.articles[0].aiError.Length>0,"private preflight rejection is visible in article and history");store.State.ai.allowPrivate=true;var analyzed=service.Analyze("a").GetAwaiter().GetResult();Check(analyzed.rating==4&&store.State.articles[0].category=="tech","real local AI request updates category and result");Check(server.Last.Contains("fixture-ai-token")&&!server.Last.Contains("fixture-source-token"),"AI credential isolated from feed credential");Check(store.State.articles[0].title==article.title&&store.State.articles[0].summary==article.summary,"original content remains unchanged");service.Analyze("a").GetAwaiter().GetResult();Check(server.Requests==1&&store.State.aiRequestsToday==1,"content fingerprint cache avoids repeat billing");Check(store.State.aiHistory.First().status=="cached","cache hits recorded without paid request");Reject(()=>service.Analyze("a",true).GetAwaiter().GetResult(),"daily request limit enforced");Check(server.Requests==1,"daily limit blocks actual network request");store.State.aiDay="2000-01-01";store.State.articles[0].locked=true;store.State.articles[0].category="manual";service.Analyze("a",true).GetAwaiter().GetResult();Check(store.State.articles[0].category=="manual","AI preserves manually locked category");Check(store.State.aiRequestsToday==1&&server.Requests==2,"daily request count resets on local date");server.Content=Response("{\"title\":\"bad\",\"rating\":0}");store.State.ai.dailyLimit=5;Reject(()=>service.Analyze("a",true).GetAwaiter().GetResult(),"invalid provider output is rejected in real request");Check(store.State.articles[0].ai.rating==4&&store.State.articles[0].aiError.Length>0,"failure retains prior AI result and records generic error");}
