 static void MetricTests(){CachePrefixTests();var state=new ClientState();state.ai=new AiSettings{model="m",estimateCost=true,inputCost=2,outputCost=8};state.aiHistory.Add(new AiRun{model="m",kind="auto",status="success",usageKnown=true,inputTokens=100,outputTokens=20,totalTokens=120,cachedTokens=80,cacheUsageKnown=true});state.aiHistory.Add(new AiRun{model="m",kind="auto",status="cached"});state.aiHistory.Add(new AiRun{model="m",kind="auto",status="blocked"});var metrics=Data.Json().Deserialize<Dictionary<string,object>>(Data.Json().Serialize(AiService.DailyUsage(state,DateTime.Now)));Check(Convert.ToInt32(metrics["requests"])==1&&Math.Abs(Convert.ToDouble(metrics["providerCacheRate"])-80)<0.001&&Math.Abs(Convert.ToDouble(metrics["localCacheRate"])-50)<0.001,"provider token cache and local result reuse have separate accurate rates");Check(Math.Abs(Convert.ToDouble(metrics["estimatedCost"])-0.00036)<0.00000001,"configured unit rates produce explicitly estimated cost");state.aiHistory[0].cacheUsageKnown=false;state.aiHistory[0].cachedTokens=0;metrics=Data.Json().Deserialize<Dictionary<string,object>>(Data.Json().Serialize(AiService.DailyUsage(state,DateTime.Now)));Check(!Convert.ToBoolean(metrics["cacheKnown"]),"missing provider cache metrics remain unknown");}
