  var card=new AiResult{articleType="shopping",title="100元充值卡",price="到手95元"};AiService.RefineTitle(card);Check(card.title=="100元充值卡","product denomination is not removed as selling price");
  var rebate=new AiResult{articleType="shopping",price="返后9.9元"};AiService.ValidatePrice(rebate,new Article{title="JD【19.90/返10】洗洁精1kg",summary="付款后返10元超市卡，返后9.9元"});Check(rebate.price=="实付¥19.90，返10元超市卡","rebate card is separated from actual cash payment");
  var invented=new AiResult{articleType="shopping",price="凑单¥4.90"};AiService.ValidatePrice(invented,new Article{title="JD【4.90】果味饮料50支",summary="非Plus不包邮"});Check(invented.price=="到手¥4.90","unsupported bundle condition cannot be invented");
