 }
 static void RecentContextTests(){
  var settings=new AiSettings{model="fixture",contextChars=1200,useContext=true};var state=new ClientState();state.sources.Add(new Source{id="p",url="https://example.com/feed"});state.sources.Add(new Source{id="private",url="https://example.com/private",privateSource=true});
  double now=Data.Now();var current=new Article{id="now",source="p",title="TB【凑单139.13】星河运动鞋",time=now};
  for(int i=0;i<14;i++)state.articles.Add(new Article{id="old"+i,source="p",title="TB【到手159】星河运动鞋",summary=new string('详',500)+" https://example.com/?key=secret",time=now-(i+1)*1000,ai=new AiResult{rating=5,reason="previous-rating-marker"}});
  state.articles.Add(new Article{id="secret",source="private",title="星河运动鞋 private-marker",time=now-100});state.articles.Add(new Article{id="future",source="p",title="星河运动鞋 future-marker",time=now+1000});state.articles.Add(new Article{id="unrelated",source="p",title="数据库备份 unrelated-marker",time=now-100});
  state.articles.Add(new Article{id="expired",source="p",title="星河运动鞋 expired-marker",time=now-8*86400000d});state.articles.Add(current);
  int chars;var body=AiService.Body(current,settings,state.categories);int count=AiService.AddRecentContext(body,state,settings,current,out chars);var messages=(object[])body["messages"];string payload=Data.Json().Serialize(messages[messages.Length-2]);
  Check(count>0&&count<=10&&chars<=1200,"related history is selected and serialized payload stays within budget");
  Check(payload.Contains("old0")&&!payload.Contains("previous-rating-marker")&&!payload.Contains("rating")&&!payload.Contains("secret"),"recent source facts retained without prior ratings or URL secrets");
  Check(!payload.Contains("private-marker")&&!payload.Contains("future-marker")&&!payload.Contains("unrelated-marker")&&!payload.Contains("expired-marker"),"private future unrelated and expired context excluded");
  Check(Data.Json().Serialize(messages.Last()).Contains("139.13"),"current article stays last after context insertion");
  var again=AiService.Body(current,settings,state.categories);AiService.AddRecentContext(again,state,settings,current,out chars);Check(Data.Json().Serialize(again)==Data.Json().Serialize(body),"identical history produces deterministic request prefix");
  settings.useContext=false;var disabled=AiService.Body(current,settings,state.categories);Check(AiService.AddRecentContext(disabled,state,settings,current,out chars)==0&&chars==0&&((object[])disabled["messages"]).Length==4,"context toggle disables all history sending");
  settings.useContext=true;settings.contextChars=400;body=AiService.Body(current,settings,state.categories);AiService.AddRecentContext(body,state,settings,current,out chars);Check(chars<=400,"minimum context budget cannot overflow");
  Reject(()=>AiService.Validate(new AiSettings{contextChars=399}),"context budget validated at backend");
  settings.contextChars=1200;string fingerprint=AiService.Fingerprint(current,settings,state.categories);settings.contextChars=1600;Check(fingerprint!=AiService.Fingerprint(current,settings,state.categories),"context configuration changes invalidate result snapshot");
 }
 static void RecentContextNetworkTests(string folder){using(var server=new Server(Response("{\"articleType\":\"shopping\",\"title\":\"星河运动鞋\",\"price\":\"凑单139.13元\",\"rating\":3}"))){
  var store=new Store(Path.Combine(folder,"related-context"));store.State.ai=new AiSettings{enabled=true,endpoint=server.Url,model="fixture",useContext=true};store.State.sources.Add(new Source{id="s",url="https://example.com/feed"});double now=Data.Now();
  store.State.articles.Add(new Article{id="old-context",source="s",title="TB【到手159】星河运动鞋",summary="一双，普通用户价格159元。",time=now-1000});
  store.State.articles.Add(new Article{id="current-context",source="s",title="TB【凑单139.13】星河运动鞋",time=now});var service=new AiService(store);service.Analyze("current-context").GetAwaiter().GetResult();
  Check(server.Requests==1&&server.Last.Contains("relatedHistory")&&server.Last.Contains("old-context")&&store.State.aiHistory.First().contextCount==1&&store.State.aiHistory.First().contextChars>0,"real request includes related history and records its exact size without extra summary calls");
  store.State.articles.Add(new Article{id="new-context",source="s",title="TB【到手149】星河运动鞋",time=now});service.Analyze("current-context").GetAwaiter().GetResult();Check(server.Requests==1,"new history does not invalidate paid result snapshots");
  service.Analyze("current-context",true).GetAwaiter().GetResult();Check(server.Requests==2&&server.Last.Contains("new-context"),"explicit reanalysis refreshes related background");
 }}
 static void RssTests(){
 var s=new AiSettings{model="m",endpoint="https://example.com/v1/chat/completions",useHistory=true};var state=new ClientState{ai=s};state.sources.Add(new Source{id="s",url="https://example.com/feed"});var current=new Article{id="a",source="s",title="新闻：新系统上线",html="<p>上线后新增离线阅读，计划分阶段开放。</p>"};
 var ordinary=new Article{id="ordinary",source="s",title="ordinary-marker",ai=new AiResult{rating=5}};var favorite=new Article{id="favorite",source="s",title="favorite-marker",summary="收藏的阅读兴趣",star=true};state.articles.AddRange(new[]{current,ordinary,favorite});
 var categories=new List<Category>{new Category{id="z",name="新闻"},new Category{id="a",name="技术"}};var one=AiService.Body(current,s,categories);AiService.AddHistory(one,state,s,current);var text=Data.Json().Serialize(one);Check(text.Contains("favorite-marker")&&!text.Contains("ordinary-marker"),"only favorites inform personal preference, never model-rated history");
 var key=AiService.FavoritesKey(state,s);ordinary.ai.rating=1;Check(key==AiService.FavoritesKey(state,s),"ordinary rating changes never invalidate favorite preference cache");favorite.star=false;Check(key!=AiService.FavoritesKey(state,s),"unfavorite invalidates preference-dependent result key");favorite.star=true;
 var other=new Article{id="b",title="教程：如何备份",summary="另一篇完全不同的文章"};var two=AiService.Body(other,s,categories.AsEnumerable().Reverse().ToList());AiService.AddHistory(two,state,s,other);var a=(object[])one["messages"];var b=(object[])two["messages"];Check(Data.Json().Serialize(a.Take(a.Length-1).ToArray())==Data.Json().Serialize(b.Take(b.Length-1).ToArray()),"stable shared prefix precedes changing article and category input order is deterministic");Check(text.Contains("先识别文章类型")&&text.Contains("非购物文章price必须为空"),"RSS title contract adapts to news tutorials research and shopping");
 current.firstSeen=Data.Now();int included,excluded;var digest=Data.Json().Serialize(AiService.DigestBody(state,s,DateTime.Now,out included,out excluded));Check(digest.Contains("新增离线阅读")&&digest.Contains("今日文章总览")&&!digest.Contains("knownTokens"),"daily digest summarizes article bodies rather than AI operational statistics");
 string json="{\"p\":{\"name\":\"Provider\",\"models\":{\"m\":{\"cost\":{\"input\":2,\"output\":8,\"cache_read\":0.2}}}}}";
 var prices=ModelPricing.Parse(json,"m");Check(prices.Count==1&&prices[0].cacheReadKnown&&prices[0].cacheRead==0.2&&ModelPricing.Parse(json,"unknown").Count==0,"models.dev exact provider/model lookup with cache-read rate");
 ModelPricing.Apply(s,prices[0]);var run=new AiRun{usageKnown=true,inputTokens=100,outputTokens=20,cachedTokens=80};AiService.RecordCost(run,s);Check(run.costKnown&&run.costCurrency=="USD"&&Math.Abs(run.estimatedCost-0.000216)<0.000000001,"cost snapshots charge cached inputs at directory cache-read price");
 s.model="different";var mismatch=new AiRun{usageKnown=true,inputTokens=100};AiService.RecordCost(mismatch,s);Check(!mismatch.costKnown,"model changes cannot silently inherit unrelated directory prices");
 Reject(()=>AiService.Validate(new AiSettings{cacheReadCost=Double.NaN}),"invalid cache rate rejected");
 var nonShopping=new AiResult{articleType="news",title="新闻",price="到手¥88"};AiService.ValidatePrice(nonShopping,new Article{title="某企业营收88亿元"});Check(nonShopping.price=="","non-shopping article never displays a product price");
 var usage=new AiRun();AiService.Usage("{\"usage\":{\"input_tokens\":100,\"output_tokens\":10,\"input_tokens_details\":{\"cached_tokens\":80}}}",usage);Check(usage.cacheUsageKnown&&usage.cachedTokens==80,"compatible input token cache metrics captured");
 }
 static string ResponseWithUsage(string content){var value=Data.Json().Deserialize<Dictionary<string,object>>(Response(content));value["usage"]=new{prompt_tokens=40,completion_tokens=20,total_tokens=60};return Data.Json().Serialize(value);}
 static string Response(string content){return Data.Json().Serialize(new{choices=new[]{new{finish_reason="stop",message=new{content=content,reasoning_content="private-thought-not-for-storage"}}}});}
 sealed class Server:IDisposable {
 readonly TcpListener listener;readonly Task task;volatile bool stopped;public int Requests;public string Content,Last="",Url;
 public Server(string content){Content=content;listener=new TcpListener(IPAddress.Loopback,0);listener.Start();Url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/v1/chat/completions";task=Task.Run(()=>{while(!stopped)try{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){client.ReceiveTimeout=5000;var buffer=new List<byte>();int value;while((value=stream.ReadByte())>=0){buffer.Add((byte)value);int n=buffer.Count;if(n>=4&&buffer[n-4]==13&&buffer[n-3]==10&&buffer[n-2]==13&&buffer[n-1]==10)break;}string headers=Encoding.UTF8.GetString(buffer.ToArray());int length=0;foreach(string line in headers.Split('\n'))if(line.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))int.TryParse(line.Substring(15).Trim(),out length);byte[] body=new byte[length];int read=0;while(read<length){int n=stream.Read(body,read,length-read);if(n<=0)break;read+=n;}Last=headers+Encoding.UTF8.GetString(body);Requests++;byte[] response=Encoding.UTF8.GetBytes(Content),head=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: "+response.Length+"\r\nConnection: close\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(response,0,response.Length);}}catch{if(stopped)break;}});}
 public void Dispose(){stopped=true;listener.Stop();task.Wait(3000);}
 }
